cards.solution:
function bandingkan(lama, baru) {
  const setLama = new Set(lama);
  const setBaru = new Set(baru);
  const ditambah = baru.filter((k) => !setLama.has(k));
  const dihapus = lama.filter((k) => !setBaru.has(k));
  console.log(ditambah.join(", "));
  console.log(dihapus.join(", "));
}
bandingkan(["P01", "P02", "P03"], ["P02", "P03", "P04", "P05"]);
